          </div>
          <h3 className="text-xs font-semibold text-foreground tracking-tight">{title}</h3>
        </div>

        {/* Tab switcher */}
        <nav className="flex items-center p-0.5 rounded-lg bg-muted border border-border" role="tablist">
          <button
